function enrichAlloy(alloy) { const fallback = ALLOY_DETAILS[alloy.series] || ALLOY_DETAILS['8000']; return {...alloy, details: alloy.details || {elements: alloy.elements || fallback.elements, mechanical: alloy.mechanical || fallback.mechanical, physical: alloy.physical || fallback.physical}}; }
function enrichAlloyData(data) { return {...data, alloys: (data.alloys || []).map(enrichAlloy)}; }
